import{c as l,$ as e,Q as o,j as s,g as a,o as i,n,m as d}from"./chunks/framework.Ce_49mA8.js";const h="/img/ru/front/capital.webp",v=JSON.parse('{"title":"Капитал (Управленческий баланс)","description":"Управленческий баланс бизнеса в реальном времени, чистые активы, структура распределения ресурсов и контроль капитала в ОмниКрафт ЕРП.","frontmatter":{"title":"Капитал (Управленческий баланс)","description":"Управленческий баланс бизнеса в реальном времени, чистые активы, структура распределения ресурсов и контроль капитала в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-14","order":4},"headers":[],"relativePath":"ru/docs/resources/capital.md","filePath":"ru/docs/resources/capital.md","lastUpdated":1794614400000}'),g={name:"ru/docs/resources/capital.md"},c={id:"капитал-управленческии-баланс-бизнеса",tabindex:"-1"};function u(p,t,b,m,f,x){const r=e("DocIcon");return o(),s("div",null,[a("h1",c,[i(r,{name:"capital"}),t[0]||(t[0]=n(" Капитал: Управленческий баланс бизнеса ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#капитал-управленческии-баланс-бизнеса","aria-label":'Permalink to "Капитал: Управленческий баланс бизнеса"'},"​",-1))]),t[2]||(t[2]=d('<figure class="doc-image craft-window-frame" data-title="Капитал (Управленческий баланс) — ОмниКрафт ЕРП"><img src="'+h+'" alt="Главное окно вкладки «Капитал» (Управленческий баланс)"><figcaption>Главное окно вкладки «Капитал» (Управленческий баланс)</figcaption></figure><p>Вкладка <strong>«Капитал»</strong> служит финансовым компасом вашего дела в реальном времени. В то время как журнал движения денег (ДДС) отвечает на оперативный вопрос <em>«Хватит ли свободных средств на завтрашние платежи?»</em>, отчет «Капитал» отвечает на главный стратегический вопрос собственника:</p><blockquote><p><strong>Сколько реально стоит весь мой бизнес прямо сейчас, если зафиксировать все активы и закрыть обязательства?</strong></p></blockquote><p>Здесь программа сводит воедино материальную базу, запасы сырья, партии готовой продукции и свободную кассу, вычитая из них накопленные долги и формируя показатель <strong>Собственного капитала (Чистых активов)</strong>.</p><hr><h2 id="математическая-модель-формула-чистых-активов" tabindex="-1">Математическая модель: Формула чистых активов <a class="header-anchor" href="#математическая-модель-формула-чистых-активов" aria-label="Permalink to &quot;Математическая модель: Формула чистых активов&quot;">​</a></h2><p>В основе работы модуля лежит фундаментальное уравнение управленческого учета:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Управленческий баланс</span><div class="formula-heading">Формула собственного капитала бизнеса</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Собственный капитал</span><span class="math-op">=</span><span class="math-calc-expr">Все материальные активы</span><span class="math-op">−</span><span class="math-calc-expr">Обязательства</span></div></div><div class="formula-card-bottom"><p>Отражает чистую стоимость бизнеса за вычетом долговых обязательств, даже при временном дефиците свободной кассы.</p></div></div><p>Пока показатель собственного капитала положителен и стабильно растет от месяца к месяцу, ваше дело развивается в плюс, даже если на расчетном счете или в ящике стола прямо сейчас немного свободных денег.</p><h3 id="закон-сохранения-и-кругооборота-стоимости" tabindex="-1">Закон сохранения и кругооборота стоимости <a class="header-anchor" href="#закон-сохранения-и-кругооборота-стоимости" aria-label="Permalink to &quot;Закон сохранения и кругооборота стоимости&quot;">​</a></h3><p>В повседневной жизни трату денег часто воспринимают как их утрату. В профессиональном учете <strong>ОмниКрафт ЕРП</strong> действует закон непрерывной трансформации активов:</p><ol><li><strong>Деньги не исчезают, а меняют форму:</strong><ol class="craft-list-steps" style="margin-top:0.8rem;"><li><div><strong>Деньги в кассе:</strong><br> Стартовые финансовые ресурсы или полученные клиентские авансы. </div></li><li><div><strong>Сырьё на складе (метод МАК):</strong><br> Закупка материалов и оприходование партий со средневзвешенной оценкой. </div></li><li><div><strong>Заказы в работе:</strong><br> Списание сырья на Верстаке и фиксация нормо-часов мастера. </div></li><li><div><strong>Готовая продукция (метод ФИФО):</strong><br> Постановка тиража на складской баланс с замороженной себестоимостью. </div></li><li><div><strong>Возврат в кассу с чистой маржой:</strong><br> Реализация изделий, закрытие кассового чека и получение коммерческой прибыли. </div></li></ol></li><li><strong>Амортизация как инвестиция:</strong> долгосрочное оборудование постепенно переносит свою балансовую стоимость на себестоимость изделий и выполненных услуг через наценку на износ. Эти средства возвращаются в кассу с выручкой, накапливая резерв на обновление станков.</li></ol><hr><h2 id="четыре-агрегата-баланса-структура-активов" tabindex="-1">Четыре агрегата баланса (Структура активов) <a class="header-anchor" href="#четыре-агрегата-баланса-структура-активов" aria-label="Permalink to &quot;Четыре агрегата баланса (Структура активов)&quot;">​</a></h2><p>Под главным числом капитала расположен блок наглядных индикаторов, показывающий, <strong>в какой именно форме</strong> сейчас работают ваши ресурсы:</p><h3 id="_1-свободные-деньги-касса" tabindex="-1">1. Свободные деньги (Касса) <a class="header-anchor" href="#_1-свободные-деньги-касса" aria-label="Permalink to &quot;1. Свободные деньги (Касса)&quot;">​</a></h3><p>Физический положительный остаток на банковских счетах и в наличных кассах. Это наиболее подвижная часть активов, готовая к немедленной закупке материалов, выплате налогов или изъятию в качестве личного дохода владельца.</p><h3 id="_2-материалы-и-сырье-на-складе" tabindex="-1">2. Материалы и сырье на складе <a class="header-anchor" href="#_2-материалы-и-сырье-на-складе" aria-label="Permalink to &quot;2. Материалы и сырье на складе&quot;">​</a></h3><p>Стоимость всех складских запасов, вычисленная по профессиональному методу <strong>скользящей средней стоимости (МАК)</strong>. Программа учитывает реальные закупочные цены партий и справедливую долю расходов на доставку, показывая честную материальную оценку полок.</p><h3 id="_3-готовая-продукция-и-выполненные-работы" tabindex="-1">3. Готовая продукция и выполненные работы <a class="header-anchor" href="#_3-готовая-продукция-и-выполненные-работы" aria-label="Permalink to &quot;3. Готовая продукция и выполненные работы&quot;">​</a></h3><ul><li>В производстве: готовые изделия на складе, оцененные строго по фактической себестоимости их выпуска (списание партий по <strong>методу ФИФО</strong>).</li><li>В сфере услуг: закрывающиеся и готовые к выдаче заказ-наряды с зафиксированной суммой деталей и выполненной работы мастеров.</li></ul><h3 id="_4-оборудование-и-долгосрочные-активы" tabindex="-1">4. Оборудование и долгосрочные активы <a class="header-anchor" href="#_4-оборудование-и-долгосрочные-активы" aria-label="Permalink to &quot;4. Оборудование и долгосрочные активы&quot;">​</a></h3><p>Остаточная стоимость всех используемых станков, инструмента, компьютеров, сервисных приборов и мебели с учетом начисленной линейной амортизации на текущий день.</p><hr><h2 id="личные-инвестиции-отрицательная-касса-в-балансе" tabindex="-1">Личные инвестиции: Отрицательная касса в балансе <a class="header-anchor" href="#личные-инвестиции-отрицательная-касса-в-балансе" aria-label="Permalink to &quot;Личные инвестиции: Отрицательная касса в балансе&quot;">​</a></h2><p>При открытии мастерской или расширении сервиса в блоке структуры активов может появиться специальная строка: <strong>«Личные инвестиции»</strong>.</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Статья баланса капитала</th><th style="width:25%;">Сумма, ₽</th><th style="width:25%;">Экономическая роль</th></tr></thead><tbody><tr><td><strong>Оборудование и станки</strong></td><td>150 000 ₽</td><td>Остаточная стоимость средств производства</td></tr><tr><td><strong>Сырьё и материалы</strong></td><td>50 000 ₽</td><td>Складские запасы по методу МАК</td></tr><tr><td><strong>Готовые изделия на складе</strong></td><td>20 000 ₽</td><td>Товарные партии по себестоимости ФИФО</td></tr><tr><td><strong>Личные инвестиции (отрицательный ДДС)</strong></td><td>−70 000 ₽</td><td>Вложения создателя в запуск мастерской</td></tr><tr><td><strong>Итого чистый капитал дела</strong></td><td><strong>150 000 ₽</strong></td><td><strong>Реальная рыночная стоимость бизнеса</strong></td></tr></tbody></table><h3 id="экономическии-смысл-личных-инвестиции" tabindex="-1">Экономический смысл личных инвестиций: <a class="header-anchor" href="#экономическии-смысл-личных-инвестиции" aria-label="Permalink to &quot;Экономический смысл личных инвестиций:&quot;">​</a></h3><ul><li>В философии смешанных финансов отрицательное сальдо кассы фиксирует факт: создатель профинансировал закупку оборудования или материалов из собственного кармана.</li><li>С точки зрения баланса эта сумма выступает обязательством предприятия перед владельцем: дело «должно» вернуть эти деньги.</li><li>Как только выручка с продаж превысит стартовые траты и сальдо ДДС станет положительным, строка личных инвестиций автоматически исчезнет, а вся дальнейшая прибыль пойдет на чистый прирост собственного капитала.</li></ul><hr><h2 id="отраслевая-специфика-баланса" tabindex="-1">Отраслевая специфика баланса <a class="header-anchor" href="#отраслевая-специфика-баланса" aria-label="Permalink to &quot;Отраслевая специфика баланса&quot;">​</a></h2><p>Базовая формула едина, однако структура капитала принципиально зависит от направления деятельности:</p><h3 id="production" tabindex="-1">В производстве и ремесле <a class="header-anchor" href="#production" aria-label="Permalink to &quot;В производстве и ремесле {#production}&quot;">​</a></h3><ul><li><strong>Характер баланса:</strong> материалоемкий и капиталоемкий.</li><li><strong>Главные центры стоимости:</strong> тяжелые станки с длительным сроком амортизации, оптовые запасы сырья на складе и готовые партии товаров в ожидании отгрузки.</li><li><strong>Фокус контроля:</strong> предотвращение затоваривания склада сырьем при низкой оборачиваемости готовой продукции.</li></ul><h3 id="services" tabindex="-1">В сфере услуг и сервисных центрах <a class="header-anchor" href="#services" aria-label="Permalink to &quot;В сфере услуг и сервисных центрах {#services}&quot;">​</a></h3><ul><li><strong>Характер баланса:</strong> сервисное оснащение и оборотные запчасти.</li><li><strong>Главные центры стоимости:</strong> диагностические комплексы, паяльные посты, подъемники, фонд ремкомплектов и закрывающиеся заказ-наряды.</li><li><strong>Фокус контроля:</strong> сопоставление фонда запчастей с реальной динамикой поступающих заказов.</li></ul><h3 id="trade" tabindex="-1">В торговле и у селлеров маркетплейсов <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;В торговле и у селлеров маркетплейсов {#trade}&quot;">​</a></h3><ul><li><strong>Характер баланса:</strong> динамичный товарный оборот.</li><li><strong>Главные центры стоимости:</strong> товарные партии на основном складе, упаковка и компактное маркировочное оборудование (термопринтеры, сканеры).</li><li><strong>Фокус контроля:</strong> удержание высокой скорости оборачиваемости запасов без оседания неликвидных артикулов.</li></ul><h3 id="masters" tabindex="-1">У частных специалистов и надомных мастеров <a class="header-anchor" href="#masters" aria-label="Permalink to &quot;У частных специалистов и надомных мастеров {#masters}&quot;">​</a></h3><ul><li><strong>Характер баланса:</strong> компактный личный арсенал.</li><li><strong>Главные центры стоимости:</strong> качественный ручной инструмент и рабочий запас материалов без тяжелых обременений.</li><li><strong>Фокус контроля:</strong> прозрачное разграничение личных накоплений и материальной базы дела.</li></ul><hr><h2 id="триада-финансовых-отчетов-капитал-ддс-и-аналитика" tabindex="-1">Триада финансовых отчетов: Капитал, ДДС и Аналитика <a class="header-anchor" href="#триада-финансовых-отчетов-капитал-ддс-и-аналитика" aria-label="Permalink to &quot;Триада финансовых отчетов: Капитал, ДДС и Аналитика&quot;">​</a></h2><p>Чтобы уверенно принимать управленческие решения, важно различать три ключевых инструмента финансового контура программы:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Критерий</th><th style="text-align:left;">Движение денег (ДДС)</th><th style="text-align:left;">Капитал (Баланс)</th><th style="text-align:left;">Аналитика (Прибыль)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Главный вопрос</strong></td><td style="text-align:left;">Хватит ли свободных денег завтра?</td><td style="text-align:left;">Сколько стоит все предприятие прямо сейчас?</td><td style="text-align:left;">Какова маржинальность и динамика выручки?</td></tr><tr><td style="text-align:left;"><strong>Что измеряет</strong></td><td style="text-align:left;">Физические поступления и списания (кассовый метод)</td><td style="text-align:left;">Все имущество, материалы и готовую продукцию за вычетом долгов</td><td style="text-align:left;">Эффективность продаж, структуру чеков и рентабельность направлений</td></tr><tr><td style="text-align:left;"><strong>Цель собственника</strong></td><td style="text-align:left;">Не допустить кассового разрыва</td><td style="text-align:left;">Наращивать чистую ценность своего бизнеса</td><td style="text-align:left;">Находить прибыльные позиции и отсекать убыточные</td></tr></tbody></table><hr><h2 id="пять-жизненных-парадоксов-собственника" tabindex="-1">Пять жизненных парадоксов собственника <a class="header-anchor" href="#пять-жизненных-парадоксов-собственника" aria-label="Permalink to &quot;Пять жизненных парадоксов собственника&quot;">​</a></h2><p>Понимание управленческого баланса защищает предпринимателя от опасных иллюзий и паники в нестандартных ситуациях:</p><h3 id="парадокс-1-в-кассе-пусто-но-бизнес-стал-богаче" tabindex="-1">Парадокс 1: В кассе пусто, но бизнес стал богаче <a class="header-anchor" href="#парадокс-1-в-кассе-пусто-но-бизнес-стал-богаче" aria-label="Permalink to &quot;Парадокс 1: В кассе пусто, но бизнес стал богаче&quot;">​</a></h3><ul><li><strong>Ситуация:</strong> Вы потратили 200 000 рублей со счета на покупку современного гравера с числовым управлением или завезли редкую партию сырья по крупной оптовой скидке.</li><li><strong>В кассе:</strong> Свободных денег практически не осталось.</li><li><strong>В балансе:</strong> Капитал не уменьшился ни на копейку, а при выгодной закупке — увеличился. Свободные деньги трансформировались в производительное имущество, готовое годами приносить прибыль.</li></ul><h3 id="парадокс-2-в-кассе-много-денег-но-бизнес-беднеет" tabindex="-1">Парадокс 2: В кассе много денег, но бизнес беднеет <a class="header-anchor" href="#парадокс-2-в-кассе-много-денег-но-бизнес-беднеет" aria-label="Permalink to &quot;Парадокс 2: В кассе много денег, но бизнес беднеет&quot;">​</a></h3><ul><li><strong>Ситуация:</strong> Вы провели тотальную распродажу запасов по цене ниже себестоимости, чтобы быстро наполнить кассу, а станки работают без технического обслуживания.</li><li><strong>В кассе:</strong> Временный всплеск свободной наличности.</li><li><strong>В балансе:</strong> Капитал стремительно падает: склады опустели с прямым финансовым убытком, а амортизационный фонд на замену изношенной техники не сформирован.</li></ul><h3 id="парадокс-3-списание-брака-и-естественная-убыль" tabindex="-1">Парадокс 3: Списание брака и естественная убыль <a class="header-anchor" href="#парадокс-3-списание-брака-и-естественная-убыль" aria-label="Permalink to &quot;Парадокс 3: Списание брака и естественная убыль&quot;">​</a></h3><ul><li><strong>Ситуация:</strong> На складе обнаружен испорченный материал или поврежденная заготовка. Вы оформляете акт списания.</li><li><strong>Влияние на кассу:</strong> Ноль рублей (деньги не списываются).</li><li><strong>Влияние на капитал:</strong> Стоимость складских запасов уменьшается на сумму списанного брака, честно отражая реальную текущую оценку предприятия.</li></ul><h3 id="парадокс-4-оценка-дела-при-привлечении-партнера" tabindex="-1">Парадокс 4: Оценка дела при привлечении партнера <a class="header-anchor" href="#парадокс-4-оценка-дела-при-привлечении-партнера" aria-label="Permalink to &quot;Парадокс 4: Оценка дела при привлечении партнера&quot;">​</a></h3><p>Если вы планируете привлечь инвестора, разделить доли или продать действующую мастерскую, отчет «Капитал» предоставляет готовую, документально подтвержденную справку о чистой твердой стоимости дела без завышенных ожиданий и спорных оценок.</p><h3 id="парадокс-5-консолидация-капитала-в-про-режиме" tabindex="-1">Парадокс 5: Консолидация капитала в ПРО-режиме <a class="header-anchor" href="#парадокс-5-консолидация-капитала-в-про-режиме" aria-label="Permalink to &quot;Парадокс 5: Консолидация капитала в ПРО-режиме&quot;">​</a></h3><p>Для пользователей с расширенными потребностями показатели рабочего пространства автоматически транслируются в модуль <strong>«Мой капитал»</strong>. Там баланс мастерской объединяется с личными банковскими вкладами, недвижимостью, инвестиционными портфелями и валютными резервами, формируя единый семейный баланс.</p><hr><h2 id="финансовая-гигиена-правило-ежемесячного-среза" tabindex="-1">Финансовая гигиена: Правило ежемесячного среза <a class="header-anchor" href="#финансовая-гигиена-правило-ежемесячного-среза" aria-label="Permalink to &quot;Финансовая гигиена: Правило ежемесячного среза&quot;">​</a></h2><p>Для уверенного контроля дел собственнику не требуется ежедневно погружаться в сложные расчетные формулы.</p><div class="tip custom-block"><p class="custom-block-title">Золотое правило первого числа</p><p>Возьмите за привычку открывать вкладку <strong>«Капитал»</strong> первого числа каждого месяца и фиксировать главное число.</p><ul><li>Если кривая капитала из месяца в месяц плавно идет вверх — вы на правильном пути, ваше дело системно наращивает мускулы.</li><li>Если при высокой выручке капитал топчется на месте или снижается — проанализируйте складские остатки на предмет залежавшихся неликвидов и проверьте нормативы заложенного износа в расценках.</li></ul></div>',61))])}const _=l(g,[["render",u]]);export{v as __pageData,_ as default};
